#include <vector>
#include <algorithm>

class Solution {
public:
    int minimumArrayLength(std::vector<int>& nums) {
        int m = *std::min_element(nums.begin(), nums.end());
        for (int x : nums) {
            if (x % m != 0) return 1;
        }
        int cnt = std::count(nums.begin(), nums.end(), m);
        return (cnt + 1) / 2;
    }
};

import java.util.Arrays;

class Solution {
    public int minimumArrayLength(int[] nums) {
        int m = Arrays.stream(nums).min().getAsInt();
        for (int x : nums) {
            if (x % m != 0) return 1;
        }
        int cnt = 0;
        for (int x : nums) {
            if (x == m) cnt++;
        }
        return (cnt + 1) / 2;
    }
}

var minimumArrayLength = function(nums) {
    let m = nums[0];
    for (const x of nums) if (x < m) m = x;
    for (const x of nums) {
        if (x % m !== 0) return 1;
    }
    let cnt = 0;
    for (const x of nums) {
        if (x === m) cnt++;
    }
    return Math.floor((cnt + 1) / 2);
};
